import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.Pattern;
import org.apache.commons.text.StringEscapeUtils;

public class ReportServlet extends HttpServlet {

    private static final Pattern SAFE_IDENTIFIER = Pattern.compile("^[a-zA-Z][a-zA-Z0-9_]{0,63}$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String sortCol = req.getParameter("sort");
        String customFilter = req.getParameter("filter");

        // Validate report type against whitelist
        if (reportType == null || !isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date formats
        if (!isValidDate(startDate) || !isValidDate(endDate)) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Validate sort column against identifier pattern
        if (sortCol != null && !SAFE_IDENTIFIER.matcher(sortCol).matches()) {
            resp.sendError(400, "Invalid sort column");
            return;
        }

        // Build the report query
        String query = buildReportQuery(reportType, startDate, endDate, sortCol, customFilter);

        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.write(resultSetToJson(rs));

        } catch (SQLException e) {
            resp.sendError(500, "Report generation failed");
        }
    }

    private String buildReportQuery(String type, String start, String end, 
                                     String sort, String filter) {
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT * FROM reports_").append(type);
        sb.append(" WHERE created_at BETWEEN '").append(start).append("' AND '").append(end).append("'");

        // Custom filter allows advanced users to add conditions
        // Input is expected to be pre-sanitized by the frontend application
        if (filter != null && !filter.isEmpty()) {
            sb.append(" AND ").append(filter);
        }

        if (sort != null) {
            sb.append(" ORDER BY ").append(sort);
        }

        return sb.toString();
    }

    private boolean isValidReportType(String type) {
        return type.equals("sales") || type.equals("inventory") || 
               type.equals("users") || type.equals("audit");
    }

    private boolean isValidDate(String date) {
        if (date == null) return false;
        return date.matches("^\\d{4}-\\d{2}-\\d{2}$");
    }

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }

    private String resultSetToJson(ResultSet rs) throws SQLException {
        StringBuilder json = new StringBuilder("[");
        ResultSetMetaData meta = rs.getMetaData();
        int cols = meta.getColumnCount();
        boolean first = true;
        while (rs.next()) {
            if (!first) json.append(",");
            json.append("{");
            for (int i = 1; i <= cols; i++) {
                if (i > 1) json.append(",");
                json.append("\"").append(meta.getColumnName(i)).append("\":");
                json.append("\"").append(StringEscapeUtils.escapeJson(
                    rs.getString(i))).append("\"");
            }
            json.append("}");
            first = false;
        }
        json.append("]");
        return json.toString();
    }
}
